  const items = rows.map(([id,label,category,keywords]) => ({id,label,category,keywords}));
  const shapes = new Map(rows.map(row => [row[0],row[4]]));
  let currentId, currentPath;
  function path(id) {
    if (currentId === id) return currentPath;
    const outline = shapes.get(id);
    if (!outline) return [];
    currentPath = Array.from(outline.matchAll(/([MLCZ])([^MLCZ]*)/g), ([,op,coords]) =>
      coords ? [op,...coords.split(' ').map(Number)] : [op]);
    currentId = id;
    return currentPath;
  }
  return Object.freeze({items,path});
